internal static class WindowsDisplayTests {
 const string One=@"\\.\DISPLAY1",Two=@"\\.\DISPLAY2";
 static int Count;
 static void Check(bool b,string name){if(!b)throw new Exception("FAIL "+name);Count++;}
 static void Reject(Action action,string code,string name){try{action();throw new Exception("Accepted "+name);}catch(WindowsDisplayError e){Check(e.Code==code,name);}}
 static DisplayNativeDevice Device(string name,string id,string description,uint flags){return new DisplayNativeDevice{cb=840,DeviceName=name,DeviceID=id,DeviceString=description,StateFlags=flags};}
 static DisplayNativeMode Mode(uint hz){return new DisplayNativeMode{dmDeviceName="fakeDriver",dmSpecVersion=0x401,dmSize=220,dmFields=WindowsDisplayRules.RequiredModeFields|WindowsDisplayRules.DmPosition|WindowsDisplayRules.DmOrientation|WindowsDisplayRules.DmFlags,dmBitsPerPel=32,dmPelsWidth=1920,dmPelsHeight=1080,dmDisplayFrequency=hz,dmPositionX=0,dmPositionY=0,dmDisplayOrientation=0};}
 sealed class Fake:IWindowsDisplayApi {
  public List<DisplayNativeDevice> Adapters=new List<DisplayNativeDevice>();
  public Dictionary<string,List<DisplayNativeDevice>> Monitors=new Dictionary<string,List<DisplayNativeDevice>>();
  public Dictionary<string,DisplayNativeMode> Current=new Dictionary<string,DisplayNativeMode>();
  public Dictionary<string,List<DisplayNativeMode>> Modes=new Dictionary<string,List<DisplayNativeMode>>();
  public List<DisplayPathInfo> Paths=new List<DisplayPathInfo>();
  public List<uint> Flags=new List<uint>();public List<string> Names=new List<string>();public List<DisplayNativeMode> Requests=new List<DisplayNativeMode>();
  public int Reads,TestStatus,ApplyStatus;public bool ThrowTopology,IgnoreApply,ThrowReadback,ThrowApply,KeepFractional,AbsentCurrent;public Action AfterTest,AfterApply;
  public Fake(){Adapters.Add(Device(One,"adapter","NVIDIA GPU",5));Adapters.Add(Device(Two,"adapter2","Other GPU",1));Monitors[One]=new List<DisplayNativeDevice>{Device(One+@"\Monitor0","monitor-a","Generic PnP",1)};Monitors[Two]=new List<DisplayNativeDevice>{Device(Two+@"\Monitor0","monitor-b","Other Screen",1)};Current[One]=Mode(60);var other=Mode(120);other.dmPositionX=1920;Current[Two]=other;Modes[One]=new List<DisplayNativeMode>{Mode(60),Mode(120),Mode(144),Mode(60)};Modes[Two]=new List<DisplayNativeMode>{Mode(60),Mode(120)};Paths.Add(Path(One,"monitor-a","Panel A",60000,1000));Paths.Add(Path(Two,"monitor-b","Panel B",120000,1000));}
  static DisplayPathInfo Path(string source,string id,string name,uint n,uint d){return new DisplayPathInfo{SourceDeviceName=source,MonitorDevicePath=id,FriendlyName=name,Active=true,TargetAvailable=true,Rotation=1,RefreshNumerator=n,RefreshDenominator=d};}
  public bool EnumDevice(string parent,uint index,uint flags,out DisplayNativeDevice device){Reads++;var list=parent==null?Adapters:Monitors.ContainsKey(parent)?Monitors[parent]:new List<DisplayNativeDevice>();device=new DisplayNativeDevice();if(index>=list.Count)return false;device=list[(int)index];return true;}
  public bool EnumMode(string name,uint index,out DisplayNativeMode mode){Reads++;if(ThrowReadback&&Flags.Any(f=>f==0))throw new Exception("fake readback error");mode=new DisplayNativeMode();if(index==WindowsDisplayRules.EnumCurrent){if(AbsentCurrent||!Current.ContainsKey(name))return false;mode=Current[name];return true;}if(!Modes.ContainsKey(name)||index>=Modes[name].Count)return false;mode=Modes[name][(int)index];return true;}
  public DisplayPathInfo[] ActivePaths(){Reads++;if(ThrowTopology)throw new Exception("fake topology failure");return Paths.ToArray();}
  public int ChangeMode(string name,ref DisplayNativeMode mode,uint flags){Flags.Add(flags);Names.Add(name);Requests.Add(mode);if(flags==WindowsDisplayRules.CdsTest){if(AfterTest!=null)AfterTest();return TestStatus;}if(ThrowApply)throw new Exception("fake driver exception");if(ApplyStatus==0&&!IgnoreApply){Current[name]=mode;foreach(var p in Paths.Where(p=>p.SourceDeviceName==name)){if(KeepFractional){p.RefreshNumerator=60000;p.RefreshDenominator=1001;}else{p.RefreshNumerator=mode.dmDisplayFrequency;p.RefreshDenominator=1;}}}if(AfterApply!=null)AfterApply();return ApplyStatus;}
 }
 static WindowsDisplayScreen Screen(WindowsDisplayController c){return c.Read().Screens.First(s=>s.DeviceName==One);}
