   int demands=0;var guardedNative=new WindowsDisplayNativeApi(()=>{demands++;throw new InvalidOperationException("session disabled");});Check(demands==0,"native constructor has no guard call/I/O");var guardedMode=Mode(60);Reject(()=>guardedNative.ChangeMode(One,ref guardedMode,2),"WRITE_POLICY_BLOCKED","policy before real CDS_TEST");Reject(()=>guardedNative.ChangeMode(One,ref guardedMode,0),"WRITE_POLICY_BLOCKED","policy before real display change");Check(demands==2,"each native transition rechecks policy without calling User32");
