   var same=c.ApplyRefreshRate(s,60,true);Check(same.AlreadyCurrent&&!same.WriteAttempted&&f.Flags.Count==0,"same integer rate no-op");var foreign=new WindowsDisplayController(f);Reject(()=>foreign.ApplyRefreshRate(s,120,true),"FOREIGN_SNAPSHOT","foreign controller snapshot rejected");
