   f=new Fake{ThrowReadback=true};c=new WindowsDisplayController(f);result=c.ApplyRefreshRate(Screen(c),120,true);Check(result.WriteAttempted&&result.OriginalMode.ReportedRefreshRateHz==60&&result.ErrorCode=="MODE_READBACK_FAILED","original survives readback exception");
   f=new Fake{ThrowApply=true};c=new WindowsDisplayController(f);result=c.ApplyRefreshRate(Screen(c),120,true);Check(result.WriteAttempted&&!result.ReadbackConfirmed&&result.OriginalMode.ReportedRefreshRateHz==60,"original survives apply exception");
   f=new Fake();f.Paths.Add(new DisplayPathInfo{SourceDeviceName=One,MonitorDevicePath="cloned-target",FriendlyName="Clone",Active=true,TargetAvailable=true,Rotation=1,RefreshNumerator=60,RefreshDenominator=1});c=new WindowsDisplayController(f);snapshot=c.Read();Check(snapshot.Screens.Count==3&&snapshot.Screens.Where(x=>x.DeviceName==One).All(x=>x.SharedModeGroup&&!x.ManualRefreshSupported),"cloned group not writable independently");Reject(()=>c.ApplyRefreshRate(snapshot.Screens[0],120,true),"DISPLAY_MODE_UNAVAILABLE","clone gate");Check(f.Flags.Count==0,"clone gate zero setter");
